$(function(){var i=$(".facilityArea__map");map_all=i.find('map[name="MAP0"] area').on("click",function(){var n=$(this).attr("href").substr(1);i.find(".map_"+n).css("z-index","2").siblings().css("z-index","1"),i.find(".map_close").show()}),$(".map_close").on("click",function(){i.find(".map_all").css("z-index","2").siblings().css("z-index","1"),$(this).hide()})});